import type { CSSProperties, ImgHTMLAttributes } from 'react';
import type { RemoteImage } from '../../content/types';

export interface ImageVariant {
  w: number;
  url: string;
}

/** Entry of assets/opt/manifest.ts (generated by scripts/optimize-site-images.mjs). */
export interface OptimizedImage {
  width: number;
  height: number;
  avif: ImageVariant[];
  webp: ImageVariant[];
  /** ~300-byte blurred preview, painted as background until the real image decodes. */
  placeholder: string;
  color: string;
}

export function toSrcSet(variants: ImageVariant[]): string {
  return variants.map((v) => `${v.url} ${v.w}w`).join(', ');
}

function isOptimized(image: OptimizedImage | RemoteImage): image is OptimizedImage {
  return 'avif' in image && Array.isArray(image.avif);
}

interface PictureProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, 'src' | 'srcSet' | 'width' | 'height' | 'alt' | 'loading'> {
  /** Bundled image from the manifest, or an admin-uploaded one. */
  image: OptimizedImage | RemoteImage;
  /** Meaningful description, or '' for purely decorative images. Required on purpose. */
  alt: string;
  /**
   * How wide the image renders, e.g. «(min-width: 1024px) 405px, 100vw».
   * Wrong `sizes` = phones downloading desktop images. Never omit for non-full-width images.
   */
  sizes: string;
  /** true only for the above-the-fold LCP image: eager + fetchpriority=high. Everything else lazy-loads. */
  priority?: boolean;
  /** Class for the <picture> wrapper; `className` goes to the <img>. */
  wrapperClassName?: string;
}

/**
 * Responsive AVIF → WebP image with intrinsic dimensions (no layout shift) and a blur-up placeholder.
 * Size it with CSS on `className` (usually width:100%; height:100%; object-fit:cover).
 */
export function Picture({ image, alt, sizes, priority = false, wrapperClassName, className, style, ...rest }: PictureProps) {
  const loading = priority ? 'eager' : 'lazy';
  const fetchPriority = priority ? 'high' : undefined;

  if (isOptimized(image)) {
    const fallback = image.webp[Math.min(2, image.webp.length - 1)];
    const placeholderStyle: CSSProperties = {
      backgroundColor: image.color,
      backgroundImage: `url("${image.placeholder}")`,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      ...style,
    };
    return (
      <picture className={wrapperClassName}>
        <source type="image/avif" srcSet={toSrcSet(image.avif)} sizes={sizes} />
        <source type="image/webp" srcSet={toSrcSet(image.webp)} sizes={sizes} />
        <img
          src={fallback.url}
          width={image.width}
          height={image.height}
          alt={alt}
          loading={loading}
          decoding={priority ? 'sync' : 'async'}
          fetchPriority={fetchPriority}
          className={className}
          style={placeholderStyle}
          {...rest}
        />
      </picture>
    );
  }

  return (
    <picture className={wrapperClassName}>
      {image.avifSrcSet ? <source type="image/avif" srcSet={image.avifSrcSet} sizes={sizes} /> : null}
      {image.webpSrcSet ? <source type="image/webp" srcSet={image.webpSrcSet} sizes={sizes} /> : null}
      <img
        src={image.src}
        width={image.width}
        height={image.height}
        alt={alt}
        loading={loading}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={fetchPriority}
        className={className}
        style={style}
        {...rest}
      />
    </picture>
  );
}
